53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	const LOYALTY_YEARS_THRESHOLD = 2;
59	const LOYALTY_DISCOUNT_RATE = 0.2;
60	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
61	
62	// Spec price list: each item type has an insurance value and a base premium.
63	const PRICE_LIST: Record<
64	  string,
65	  { insuranceValue: number; basePremium: number }
66	> = {
67	  sword: { insuranceValue: 1000, basePremium: 100 },
68	  amulet: { insuranceValue: 600, basePremium: 60 },
69	  staff: { insuranceValue: 800, basePremium: 80 },
70	  potion: { insuranceValue: 400, basePremium: 40 },
71	  rune: { insuranceValue: 250, basePremium: 25 },
72	  moonstone: { insuranceValue: 250, basePremium: 25 },
73	};
74	
75	const sumOf = <T>(items: T[], valueOf: (item: T) => number): number =>
76	  items.reduce((sum, item) => sum + valueOf(item), 0);
77	
78	const countWhere = <T>(items: T[], matches: (item: T) => boolean): number =>
79	  items.filter(matches).length;
80	
81	const basePremiumOf = (type: string): number => PRICE_LIST[type].basePremium;
82	
83	const insuranceValueOf = (type: string): number =>
84	  PRICE_LIST[type].insuranceValue;
85	
86	// "A building block of 3 alike components is offered at a special base premium of 60 G."
87	const COMPONENT_TYPES = ["rune", "moonstone"];
88	const BLOCK_SIZE = 3;
89	const COMPONENT_BLOCK_PREMIUM = 60;
90	
91	const componentBlockDiscount = (items: QuoteItem[]): number =>
92	  sumOf(COMPONENT_TYPES, (type) => {
93	    const count = countWhere(items, (item) => item.type === type);
94	    return count === BLOCK_SIZE
95	      ? BLOCK_SIZE * basePremiumOf(type) - COMPONENT_BLOCK_PREMIUM
96	      : 0;
97	  });
98	
99	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
100	
101	const isLoyalCustomer = (customer: Customer): boolean =>
102	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
103	
104	const isHighlyEnchanted = (item: QuoteItem): boolean =>
105	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
106	
107	// Surcharges apply per item, as a percentage of that item's base premium.
108	const surchargeOn = (
109	  items: QuoteItem[],
110	  applies: (item: QuoteItem) => boolean,
111	  rate: number,
112	): number =>
113	  sumOf(items, (item) =>
114	    applies(item) ? basePremiumOf(item.type) * rate : 0,
115	  );
116	
117	const quotePremium = (
118	  items: QuoteItem[],
119	  customer: Customer,
120	  isFollowUpContract: boolean,
121	): number => {
122	  const itemBase = sumOf(items, (item) => basePremiumOf(item.type));
123	  const policyBase = itemBase - componentBlockDiscount(items);
124	  const curseSurcharge = surchargeOn(items, isCursed, CURSE_SURCHARGE_RATE);
125	  const highEnchantmentSurcharge = surchargeOn(
126	    items,
127	    isHighlyEnchanted,
128	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
129	  );
130	  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
131	  const loyaltyDiscount = isLoyalCustomer(customer)
132	    ? policyBase * LOYALTY_DISCOUNT_RATE
133	    : 0;
134	  const followUpDiscount = isFollowUpContract
135	    ? policyBase * FOLLOW_UP_DISCOUNT_RATE
136	    : 0;
137	  return Math.ceil(
138	    policyBase +
139	      curseSurcharge +
140	      highEnchantmentSurcharge +
141	      firstInsurance -
142	      loyaltyDiscount -
143	      followUpDiscount +
144	      PROCESSING_FEE,
145	  );
146	};
147	
148	const DEDUCTIBLE = 100;
149	const CAP_MULTIPLIER = 2;
150	// "Items with an enchantment level of 8 or higher are reimbursed at 50%."
151	const CLAIM_ENCHANTMENT_THRESHOLD = 8;
152	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
153	
154	const reimbursementFor = (damage: Damage, insuredItem: QuoteItem): number =>
155	  (insuredItem.enchantment ?? 0) >= CLAIM_ENCHANTMENT_THRESHOLD
156	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
157	    : damage.amount;
158	
159	const insuranceSum = (policy: QuoteStep): number =>
160	  sumOf(policy.items, (item) => insuranceValueOf(item.type));
161	
162	// "The payout cap is twice the insurance sum" — unmodified by premium surcharges/discounts.
163	const policyCap = (policy: QuoteStep): number =>
164	  CAP_MULTIPLIER * insuranceSum(policy);
165	
166	const insuredItemFor = (policy: QuoteStep, itemType: string): QuoteItem => {
167	  const insuredItem = policy.items.find((item) => item.type === itemType);
168	  if (insuredItem === undefined) {
169	    throw new Error(
170	      `Claim rejected: no insured item of type "${itemType}" in the policy`,
171	    );
172	  }
173	  return insuredItem;
174	};
175	
176	// "You can only claim as many items of a type as the policy insures."
177	const rejectIfMoreDamagesThanInsured = (
178	  damages: Damage[],
179	  policy: QuoteStep,
180	): void => {
181	  for (const itemType of new Set(damages.map((damage) => damage.itemType))) {
182	    const damagedCount = countWhere(damages, (d) => d.itemType === itemType);
183	    const insuredCount = countWhere(policy.items, (item) => item.type === itemType);
184	    if (damagedCount > insuredCount) {
185	      throw new Error(
186	        `Claim rejected: ${damagedCount} damage entries for "${itemType}" but only ${insuredCount} insured`,
187	      );
188	    }
189	  }
190	};
191	
192	const settleClaim = (
193	  claim: ClaimStep,
194	  policy: QuoteStep,
195	  remainingCapBefore: number,
196	): ClaimResult => {
197	  for (const damage of claim.incident.damages) {
198	    if (damage.amount < 0) {
199	      throw new Error(
200	        `Claim rejected: negative damage amount ${damage.amount} for "${damage.itemType}"`,
201	      );
202	    }
203	  }
204	  rejectIfMoreDamagesThanInsured(claim.incident.damages, policy);
205	  const rawPayout = sumOf(
206	    claim.incident.damages,
207	    (damage) =>
208	      reimbursementFor(damage, insuredItemFor(policy, damage.itemType)) -
209	      DEDUCTIBLE,
210	  );
211	  const payout = Math.min(Math.floor(rawPayout), remainingCapBefore);
212	  return { payout, remainingCap: remainingCapBefore - payout };
213	};
214	
215	export const runScenario = (scenario: Scenario): ScenarioOutput => {
216	  const remainingCaps = new Map<number, number>();
217	  const results = scenario.steps.map((step, index): StepResult => {
218	    if (step.op === "claim") {
219	      const policy = scenario.steps[step.policy] as QuoteStep;
220	      const remainingCapBefore =
221	        remainingCaps.get(step.policy) ?? policyCap(policy);
222	      const result = settleClaim(step, policy, remainingCapBefore);
223	      remainingCaps.set(step.policy, result.remainingCap);
224	      return result;
225	    }
226	    const isFollowUpContract = index > 0;
227	    return {
228	      premium: quotePremium(step.items, scenario.customer, isFollowUpContract),
229	    };
230	  });
231	  return { results };
232	};
